-- Reference relational schema; adapt types and constraints to Dataverse/SQL platform.
CREATE TABLE Employee (EmployeeId VARCHAR(40) PRIMARY KEY, FullName VARCHAR(160) NOT NULL, WorkEmail VARCHAR(254) NOT NULL UNIQUE, Department VARCHAR(100), ManagerName VARCHAR(160), StartDate DATE, LastWorkingDate DATE, LifecycleState VARCHAR(30) NOT NULL);
CREATE TABLE LifecycleCase (CaseId INTEGER PRIMARY KEY, EmployeeId VARCHAR(40) NOT NULL REFERENCES Employee(EmployeeId), CaseType VARCHAR(20) NOT NULL CHECK (CaseType IN ('Onboarding','Offboarding')), EventDate DATE NOT NULL, OwnerTeam VARCHAR(80), Status VARCHAR(30) NOT NULL, Notes VARCHAR(2000), CreatedAt TIMESTAMP NOT NULL, UpdatedAt TIMESTAMP NOT NULL);
CREATE TABLE LifecycleTask (TaskId INTEGER PRIMARY KEY, CaseId INTEGER NOT NULL REFERENCES LifecycleCase(CaseId), Title VARCHAR(200) NOT NULL, AssignedTeam VARCHAR(80), DueDate DATE, Status VARCHAR(20) NOT NULL, CompletedAt TIMESTAMP, EvidenceUrl VARCHAR(500));
CREATE TABLE Approval (ApprovalId INTEGER PRIMARY KEY, CaseId INTEGER NOT NULL REFERENCES LifecycleCase(CaseId), TaskId INTEGER REFERENCES LifecycleTask(TaskId), Approver VARCHAR(160) NOT NULL, Decision VARCHAR(20), Comments VARCHAR(1000), DecidedAt TIMESTAMP);
CREATE TABLE Activity (ActivityId INTEGER PRIMARY KEY, CaseId INTEGER NOT NULL REFERENCES LifecycleCase(CaseId), Actor VARCHAR(160), Action VARCHAR(120) NOT NULL, Detail VARCHAR(1000), OccurredAt TIMESTAMP NOT NULL);
